public Batch executeTask(Map<String,String> analysisProperties, Object... components) {
  checkStarted();
  configureTaskLogging(analysisProperties);
  bootstrapContainer.executeTask(analysisProperties, components);
  try {
    configureLogging();
  } catch (ClassCastException | NullPointerException | UnsupportedOperationException | IllegalArgumentException e) {
    // Handle the exception, e.g., log it or take other corrective actions
    e.printStackTrace();
  }
  return this;
}
